style.css:
@-moz-document domain("youtube.com") {
html, body {
        height: 100% !important;
        margin: 0 !important;
        padding: 0 !important;
        background-color: black !important;
        background-image: url('https://www.animeexplained.com/wp-content/uploads/2023/11/invincibles-all-marks-explained-e1699612838999.webp') !important;
        background-repeat: no-repeat !important;
        background-size: cover !important;
        background-attachment: fixed !important;
    }

    #content, ytd-app, ytd-page-manager, ytd-player, #masthead-container, #secondary, .ytp-chrome-bottom {
        background-color: rgba(255, 255, 255, 0.8) !important;
        border-radius: 10px !important;
    }

    #masthead-container {
        background-color: rgba(0, 0, 0, 0.8) !important;
        color: #0000 !important;
        border-bottom: 3px solid #FF4500 !important;
    }

    ytd-video-primary-info-renderer h1, ytd-video-primary-info-renderer #title {
        color: #FF4500 !important;
        font-weight: bold !important;
    }

    ytd-video-primary-info-renderer #description {
        color: #0000 !important;
        font-size: 16px !important;
        line-height: 1.5 !important;
    }

    .ytp-progress-bar-container {
        background-color: #FF4500 !important;
    }

    ytd-comment-thread-renderer {
        background-color: rgba(0, 0, 0, 0.5) !important;
        color: #0000 !important;
        border-radius: 5px !important;
    }

    button, a {
        background-color: #FF4500 !important;
        color: #fff !important;
        border-radius: 8px !important;
    }

    ytd-comment-simplebox-renderer #simplebox-placeholder {
        background-color: rgba(255, 182, 193, 0.5) !important;
        border-radius: 8px !important;
    }
}
